/* AIVIC_FUNCTION_BUNDLE_START owner=sendDailyReportAndNotify exports=sendDailyReportAndNotify */
const __aivicBundle_19_sendDailyReportAndNotify = (() => {
  async function sendDailyReportAndNotify(params: {
    user_id: string;
    email_address: string;
    user_name: string;
    yesterday_work: string;
    today_plan: string;
    current_issue: string;
    submission_datetime: string;
  }): Promise<{ report_id: string; status: string }> {
    if (!params.user_id || params.user_id.trim() === "") {
      throw new Error("ユーザーID は必須です");
    }
  
    if (!params.email_address || params.email_address.trim() === "") {
      throw new Error("メールアドレスは必須です");
    }
  
    const reportId = `report_${randomUUID()}`;
  
    const emailSubject = "朝会報告確認";
    const emailBody = `
  ユーザー名: ${params.user_name}
  昨日の成果: ${params.yesterday_work}
  本日の予定: ${params.today_plan}
  現在の課題: ${params.current_issue}
  提出日時: ${params.submission_datetime}
    `.trim();
  
    const mailPayload = {
      recipient: params.email_address,
      subject: emailSubject,
      body: emailBody,
    };
  
    const response = await fetch("/api/send-mail", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(mailPayload),
    });
  
    if (!response.ok) {
      const statusText = response.status.toString();
      throw new Error(`メール送信に失敗しました: ${statusText}`);
    }
  
    return {
      report_id: reportId,
      status: "sent",
    };
  }
  return { sendDailyReportAndNotify };
})();
